"""AST node definitions shared by the parser, evaluator, and engine."""

from dataclasses import dataclass, field
from typing import Any, Iterator, List, Optional


class Expr:
    """Base class for expression nodes.

    ``text`` holds the exact source text of the expression as written in the
    query.  The parser assigns it after constructing each node.  It is not
    part of structural equality (see :func:`expr_key`).
    """

    text = ""


@dataclass
class Literal(Expr):
    value: Any


@dataclass
class Column(Expr):
    name: str


@dataclass
class Star(Expr):
    pass


@dataclass
class Unary(Expr):
    op: str
    operand: Expr


@dataclass
class Binary(Expr):
    op: str
    left: Expr
    right: Expr


@dataclass
class IsNull(Expr):
    operand: Expr
    negated: bool = False


@dataclass
class InList(Expr):
    operand: Expr
    items: List[Expr] = field(default_factory=list)
    negated: bool = False


@dataclass
class Between(Expr):
    operand: Expr
    low: Expr
    high: Expr
    negated: bool = False


@dataclass
class Like(Expr):
    operand: Expr
    pattern: Expr
    negated: bool = False


@dataclass
class Func(Expr):
    name: str  # always upper-case
    args: List[Expr] = field(default_factory=list)
    star: bool = False


@dataclass
class SelectItem:
    expr: Expr
    alias: Optional[str] = None


@dataclass
class OrderItem:
    expr: Expr
    desc: bool = False


@dataclass
class Query:
    columns: List[SelectItem] = field(default_factory=list)
    table: str = ""
    distinct: bool = False
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: int = 0


def walk(expr: Expr) -> Iterator[Expr]:
    """Yield ``expr`` and every expression node below it."""
    yield expr
    if isinstance(expr, Unary):
        yield from walk(expr.operand)
    elif isinstance(expr, Binary):
        yield from walk(expr.left)
        yield from walk(expr.right)
    elif isinstance(expr, IsNull):
        yield from walk(expr.operand)
    elif isinstance(expr, InList):
        yield from walk(expr.operand)
        for item in expr.items:
            yield from walk(item)
    elif isinstance(expr, Between):
        yield from walk(expr.operand)
        yield from walk(expr.low)
        yield from walk(expr.high)
    elif isinstance(expr, Like):
        yield from walk(expr.operand)
        yield from walk(expr.pattern)
    elif isinstance(expr, Func):
        for arg in expr.args:
            yield from walk(arg)


def _value_key(value: Any):
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, (int, float)):
        return ("num", value)
    return ("str", value)


def expr_key(expr: Expr):
    """A structural key for an expression, ignoring source text.

    Column names are compared case-insensitively because all column lookup is
    case-insensitive.
    """
    if isinstance(expr, Literal):
        return ("literal", _value_key(expr.value))
    if isinstance(expr, Column):
        return ("column", expr.name.casefold())
    if isinstance(expr, Star):
        return ("star",)
    if isinstance(expr, Unary):
        return ("unary", expr.op, expr_key(expr.operand))
    if isinstance(expr, Binary):
        return ("binary", expr.op, expr_key(expr.left), expr_key(expr.right))
    if isinstance(expr, IsNull):
        return ("isnull", expr.negated, expr_key(expr.operand))
    if isinstance(expr, InList):
        return (
            "in",
            expr.negated,
            expr_key(expr.operand),
            tuple(expr_key(item) for item in expr.items),
        )
    if isinstance(expr, Between):
        return (
            "between",
            expr.negated,
            expr_key(expr.operand),
            expr_key(expr.low),
            expr_key(expr.high),
        )
    if isinstance(expr, Like):
        return (
            "like",
            expr.negated,
            expr_key(expr.operand),
            expr_key(expr.pattern),
        )
    if isinstance(expr, Func):
        return (
            "func",
            expr.name,
            expr.star,
            tuple(expr_key(arg) for arg in expr.args),
        )
    raise TypeError("unknown expression node: %r" % (expr,))
