"""Shared helpers for the minisql test suite."""

import csv
import os
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DATA_DIR = ROOT / "data"


class MiniSQLTestCase(unittest.TestCase):
    """A test case with a private temporary directory for CSV tables."""

    def setUp(self):
        super().setUp()
        self._temporary_directory = tempfile.TemporaryDirectory(prefix="minisql-test-")
        self.addCleanup(self._temporary_directory.cleanup)
        self.directory = self._temporary_directory.name

    def write_csv(self, name, header, rows):
        """Write ``<name>.csv`` in the test directory and return its path."""
        path = Path(self.directory) / (name + ".csv")
        with path.open("w", newline="", encoding="utf-8") as handle:
            writer = csv.writer(handle)
            writer.writerow(header)
            for row in rows:
                writer.writerow(row)
        return str(path)

    def run_query(self, sql, directory=None):
        # Imported lazily so test collection works even while the engine is
        # still being written by another agent.
        from minisql import run

        if directory is None:
            directory = self.directory
        return run(sql, directory)

    def query(self, sql):
        return self.run_query(sql)

    def rows(self, sql, directory=None):
        return self.run_query(sql, directory).rows

    def columns(self, sql, directory=None):
        return self.run_query(sql, directory).columns

    def value(self, expression, table="one"):
        result = self.run_query("SELECT %s FROM %s" % (expression, table))
        self.assertEqual(
            len(result.rows), 1, "expected exactly one result row for %r" % expression
        )
        return result.rows[0][0]

    def assertQueryError(self, sql, directory=None):
        from minisql import QueryError

        with self.assertRaises(
            QueryError, msg="expected QueryError for query %r" % sql
        ):
            self.run_query(sql, directory)


def old_python_path():
    return os.environ.get("PYTHONPATH", "")

