"""Expression semantics: precedence, NULL logic, operators, and functions."""

import unittest

from tests.support import MiniSQLTestCase


class ExpressionTestCase(MiniSQLTestCase):
    def setUp(self):
        super().setUp()
        self.write_csv("one", ["x"], [[1]])

    def value(self, expression):
        return super().value(expression, "one")

    def assertValue(self, expression, expected):
        self.assertEqual(self.value(expression), expected)

    def assertNull(self, expression):
        self.assertIsNone(self.value(expression), "%s should be NULL" % expression)

    def assertExpressionError(self, expression):
        self.assertQueryError("SELECT %s FROM one" % expression)


class PrecedenceTests(ExpressionTestCase):
    def test_multiplication_before_addition(self):
        self.assertValue("1 + 2 * 3", 7)
        self.assertValue("2 * 3 + 1", 7)

    def test_parentheses_override_precedence(self):
        self.assertValue("(1 + 2) * 3", 9)
        self.assertValue("1 + 2 * (3 + 1)", 9)

    def test_addition_and_subtraction_are_left_associative(self):
        self.assertValue("10 - 2 - 3", 5)
        self.assertValue("1 + 2 + 3", 6)

    def test_division_is_left_associative(self):
        self.assertEqual(self.value("20 / 5 / 2"), 2.0)

    def test_unary_minus_binds_tighter_than_multiplication(self):
        self.assertValue("-2 * 3", -6)
        self.assertValue("-(2 + 3)", -5)
        self.assertValue("-(-4)", 4)

    def test_and_binds_tighter_than_or(self):
        self.assertValue("FALSE AND FALSE OR TRUE", True)
        self.assertValue("FALSE OR FALSE AND TRUE", False)

    def test_not_binds_tighter_than_and(self):
        self.assertValue("NOT FALSE AND FALSE", False)
        self.assertValue("NOT (FALSE AND FALSE)", True)

    def test_not_is_looser_than_comparison(self):
        self.assertValue("NOT 1 = 2", True)
        self.assertValue("NOT 1 = 1", False)
        self.assertValue("NOT 5 IN (1, 2)", True)

    def test_not_is_looser_than_between(self):
        self.assertValue("NOT 5 BETWEEN 1 AND 10", False)
        self.assertValue("NOT 5 BETWEEN 6 AND 10", True)

    def test_arithmetic_binds_tighter_than_comparison(self):
        self.assertValue("1 + 2 = 3", True)
        self.assertValue("2 * 3 > 5", True)

    def test_concatenation_shares_the_addition_level_and_is_left_associative(self):
        self.assertValue("'a' || 1 || 2", "a12")
        self.assertValue("'a' || (1 + 2)", "a3")
        self.assertValue("1 + 2 || 'x'", "3x")

    def test_concatenation_then_addition_is_an_error(self):
        # ('a' || 1) + 2 -> a string plus a number.
        self.assertExpressionError("'a' || 1 + 2")


class LiteralTests(ExpressionTestCase):
    def test_integer_literal(self):
        value = self.value("42")
        self.assertEqual(value, 42)
        self.assertIs(type(value), int)

    def test_decimal_literals(self):
        self.assertEqual(self.value("2.5"), 2.5)
        self.assertEqual(self.value(".5"), 0.5)
        self.assertIs(type(self.value(".5")), float)

    def test_string_literal(self):
        self.assertValue("'abc'", "abc")
        self.assertValue("''", "")

    def test_string_literal_escapes_a_quote_by_doubling_it(self):
        self.assertValue("'it''s'", "it's")
        self.assertValue("'a''''b'", "a''b")

    def test_string_literal_may_contain_commas_and_spaces(self):
        self.assertValue("'a, b c'", "a, b c")

    def test_null_literal(self):
        self.assertNull("NULL")

    def test_boolean_literals(self):
        self.assertValue("TRUE", True)
        self.assertValue("FALSE", False)
        self.assertValue("true", True)
        self.assertValue("false", False)


class NullLogicTests(ExpressionTestCase):
    def test_boolean_three_valued_logic(self):
        cases = {
            "TRUE AND TRUE": True,
            "TRUE AND FALSE": False,
            "FALSE AND FALSE": False,
            "TRUE AND NULL": None,
            "NULL AND TRUE": None,
            "FALSE AND NULL": False,
            "NULL AND FALSE": False,
            "NULL AND NULL": None,
            "TRUE OR TRUE": True,
            "TRUE OR FALSE": True,
            "FALSE OR FALSE": False,
            "TRUE OR NULL": True,
            "NULL OR TRUE": True,
            "FALSE OR NULL": None,
            "NULL OR FALSE": None,
            "NULL OR NULL": None,
            "NOT TRUE": False,
            "NOT FALSE": True,
            "NOT NULL": None,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_null_propagates_through_arithmetic_and_concatenation(self):
        for expression in [
            "NULL + 1",
            "1 - NULL",
            "NULL * 2",
            "NULL / 2",
            "1 / NULL",
            "NULL / 0",
            "NULL || 'x'",
            "'x' || NULL",
            "-NULL",
        ]:
            with self.subTest(expression=expression):
                self.assertNull(expression)

    def test_null_propagates_through_comparisons(self):
        for expression in [
            "NULL = NULL",
            "NULL != NULL",
            "1 = NULL",
            "NULL = 1",
            "NULL < 1",
            "NULL >= 1",
            "'a' = NULL",
        ]:
            with self.subTest(expression=expression):
                self.assertNull(expression)

    def test_is_null_and_is_not_null_are_never_null(self):
        self.assertValue("NULL IS NULL", True)
        self.assertValue("NULL IS NOT NULL", False)
        self.assertValue("1 IS NULL", False)
        self.assertValue("1 IS NOT NULL", True)
        self.assertValue("(1 = NULL) IS NULL", True)

    def test_where_keeps_only_true(self):
        self.assertEqual(self.rows("SELECT x FROM one WHERE NULL"), [])
        self.assertEqual(self.rows("SELECT x FROM one WHERE NOT NULL"), [])
        self.assertEqual(self.rows("SELECT x FROM one WHERE TRUE AND NULL"), [])
        self.assertEqual(self.rows("SELECT x FROM one WHERE FALSE OR NULL"), [])
        self.assertEqual(self.rows("SELECT x FROM one WHERE FALSE AND NULL"), [])
        self.assertEqual(len(self.rows("SELECT x FROM one WHERE TRUE OR NULL")), 1)

    def test_null_operand_functions_return_null(self):
        for expression in [
            "LOWER(NULL)",
            "UPPER(NULL)",
            "LENGTH(NULL)",
            "ABS(NULL)",
            "ROUND(NULL)",
            "ROUND(NULL, 2)",
            "COALESCE(NULL, NULL)",
        ]:
            with self.subTest(expression=expression):
                self.assertNull(expression)


class ArithmeticTests(ExpressionTestCase):
    def test_integer_arithmetic_stays_integer(self):
        cases = {"1 + 2": 3, "7 - 10": -3, "2 * 3": 6, "-2 * 3": -6}
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                value = self.value(expression)
                self.assertEqual(value, expected)
                self.assertIs(type(value), int)

    def test_mixed_arithmetic_is_float(self):
        cases = {"1 + 2.0": 3.0, "5 - 1.5": 3.5, "2 * 2.5": 5.0}
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                value = self.value(expression)
                self.assertEqual(value, expected)
                self.assertIs(type(value), float)

    def test_division_is_always_float(self):
        for expression, expected in [
            ("4 / 2", 2.0),
            ("1 / 2", 0.5),
            ("6.0 / 3", 2.0),
        ]:
            with self.subTest(expression=expression):
                value = self.value(expression)
                self.assertEqual(value, expected)
                self.assertIs(type(value), float)

    def test_division_by_zero_is_null(self):
        for expression in ["1 / 0", "0 / 0", "-1 / 0", "1.0 / 0.0", "1 / (1 - 1)"]:
            with self.subTest(expression=expression):
                self.assertNull(expression)

    def test_arithmetic_on_strings_is_an_error(self):
        for expression in ["'a' + 1", "1 + 'a'", "'a' * 2", "'a' - 'b'"]:
            with self.subTest(expression=expression):
                self.assertExpressionError(expression)

    def test_arithmetic_on_booleans_is_an_error(self):
        for expression in ["TRUE + 1", "FALSE * 2", "1 - TRUE", "-TRUE"]:
            with self.subTest(expression=expression):
                self.assertExpressionError(expression)

    def test_concatenation_uses_text_of_numbers(self):
        self.assertValue("1 || 2", "12")
        self.assertValue("1.5 || 'x'", "1.5x")
        self.assertValue("'value=' || 10", "value=10")
        self.assertValue("'' || 'x'", "x")


class ComparisonTests(ExpressionTestCase):
    def test_numeric_comparisons(self):
        cases = {
            "1 = 1.0": True,
            "1 = 2": False,
            "2 > 1.5": True,
            "1 != 2": True,
            "1 <> 2": True,
            "1 <= 1": True,
            "1 >= 2": False,
            "2.5 < 3": True,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_string_comparisons_use_code_points(self):
        cases = {
            "'abc' = 'abc'": True,
            "'abc' = 'ABC'": False,
            "'a' < 'b'": True,
            "'B' < 'a'": True,
            "'Z' < 'a'": True,
            "'abc' < 'abd'": True,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_boolean_comparisons(self):
        cases = {
            "TRUE = TRUE": True,
            "TRUE = FALSE": False,
            "FALSE < TRUE": True,
            "TRUE > FALSE": True,
            "TRUE != FALSE": True,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_comparing_number_with_string_is_an_error(self):
        for expression in ["1 = '1'", "'1' = 1", "'a' < 2", "2 >= 'b'"]:
            with self.subTest(expression=expression):
                self.assertExpressionError(expression)

    def test_comparing_boolean_with_number_is_an_error(self):
        for expression in ["TRUE = 1", "1 = FALSE", "FALSE < 0"]:
            with self.subTest(expression=expression):
                self.assertExpressionError(expression)

    def test_in_list_true_false_and_null(self):
        cases = {
            "1 IN (1, 2)": True,
            "3 IN (1, 2)": False,
            "1 IN (1, NULL)": True,
            "3 IN (1, NULL)": None,
            "NULL IN (1, 2)": None,
            "'a' IN ('a', 'b')": True,
            "'z' IN ('a', 'b')": False,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_not_in(self):
        cases = {
            "1 NOT IN (2, 3)": True,
            "1 NOT IN (1, 3)": False,
            "3 NOT IN (1, NULL)": None,
            "1 NOT IN (1, NULL)": False,
            "NULL NOT IN (1)": None,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_in_with_incompatible_types_is_an_error(self):
        self.assertExpressionError("1 IN ('a')")

    def test_between_is_inclusive(self):
        cases = {
            "5 BETWEEN 1 AND 10": True,
            "5 BETWEEN 5 AND 5": True,
            "0 BETWEEN 1 AND 10": False,
            "11 BETWEEN 1 AND 10": False,
            "5 BETWEEN 1 + 1 AND 10": True,
            "'b' BETWEEN 'a' AND 'c'": True,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_between_null_semantics_follow_and(self):
        cases = {
            "5 BETWEEN NULL AND 10": None,
            "5 BETWEEN 1 AND NULL": None,
            # 6 <= 5 is FALSE, and FALSE AND NULL is FALSE.
            "5 BETWEEN 6 AND NULL": False,
            "NULL BETWEEN 1 AND 10": None,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_not_between(self):
        cases = {
            "5 NOT BETWEEN 6 AND 10": True,
            "5 NOT BETWEEN 1 AND 10": False,
            "5 NOT BETWEEN 1 AND NULL": None,
            "5 NOT BETWEEN 6 AND NULL": True,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_between_with_incompatible_types_is_an_error(self):
        self.assertExpressionError("1 BETWEEN 'a' AND 'b'")


class LikeTests(ExpressionTestCase):
    def test_like_matches_the_whole_string(self):
        cases = {
            "'hello' LIKE 'hello'": True,
            "'hello' LIKE 'hell'": False,
            "'hello' LIKE 'hello%'": True,
            "'hello' LIKE '%hello'": True,
            "'hello' LIKE '%ell%'": True,
            "'hello' LIKE 'h%'": True,
            "'hello' LIKE '%llo'": True,
            "'hello' LIKE '%'": True,
            "'' LIKE '%'": True,
            "'hello' LIKE 'Hello'": False,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_like_underscore_matches_exactly_one_character(self):
        cases = {
            "'hello' LIKE 'h_llo'": True,
            "'hello' LIKE 'h__lo'": True,
            "'hello' LIKE 'h_lo'": False,
            "'hello' LIKE 'h____'": True,
            "'hello' LIKE '_____'": True,
            "'' LIKE '_'": False,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertValue(expression, expected)

    def test_like_with_null_is_null(self):
        self.assertNull("NULL LIKE '%'")
        self.assertNull("'abc' LIKE NULL")
        self.assertNull("NULL NOT LIKE '%'")

    def test_not_like(self):
        self.assertValue("'abc' NOT LIKE 'a%'", False)
        self.assertValue("'abc' NOT LIKE 'x%'", True)
        self.assertValue("'abc' NOT LIKE 'b%'", True)

    def test_like_requires_strings(self):
        self.assertExpressionError("1 LIKE '1'")
        self.assertExpressionError("'a' LIKE 1")


class ScalarFunctionTests(ExpressionTestCase):
    def test_lower_and_upper(self):
        self.assertValue("LOWER('AbC')", "abc")
        self.assertValue("UPPER('AbC')", "ABC")
        self.assertValue("LOWER('')", "")
        self.assertValue("upper('xyz')", "XYZ")

    def test_length(self):
        self.assertValue("LENGTH('abc')", 3)
        self.assertValue("LENGTH('')", 0)
        self.assertValue("LENGTH('a b')", 3)

    def test_abs(self):
        cases = {"ABS(-5)": 5, "ABS(3)": 3, "ABS(-2.5)": 2.5, "ABS(0)": 0}
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                self.assertEqual(self.value(expression), expected)

    def test_abs_preserves_numeric_type(self):
        self.assertIs(type(self.value("ABS(-5)")), int)
        self.assertIs(type(self.value("ABS(-2.5)")), float)

    def test_round_to_integer_returns_an_integer(self):
        cases = {
            "ROUND(2.4)": 2,
            "ROUND(2.5)": 3,
            "ROUND(-2.4)": -2,
            "ROUND(-2.5)": -3,
            "ROUND(0.5)": 1,
            "ROUND(-0.5)": -1,
            "ROUND(3)": 3,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                value = self.value(expression)
                self.assertEqual(value, expected)
                self.assertIs(type(value), int)

    def test_round_to_decimal_places_returns_a_float(self):
        cases = {
            "ROUND(1.25, 1)": 1.3,
            "ROUND(-1.25, 1)": -1.3,
            "ROUND(1.2345, 2)": 1.23,
            "ROUND(2.4, 0)": 2.0,
            "ROUND(2.5, 0)": 3.0,
            "ROUND(7, 2)": 7.0,
        }
        for expression, expected in cases.items():
            with self.subTest(expression=expression):
                value = self.value(expression)
                self.assertAlmostEqual(value, expected)
                self.assertIs(type(value), float)

    def test_coalesce(self):
        self.assertValue("COALESCE(NULL, 'x', 'y')", "x")
        self.assertValue("COALESCE(NULL, NULL, 3)", 3)
        self.assertValue("COALESCE(1, 'x')", 1)
        self.assertNull("COALESCE(NULL, NULL)")
        self.assertValue("CoAlEsCe(NULL, 1)", 1)

    def test_unknown_function_is_an_error(self):
        self.assertExpressionError("NOPE(1)")

    def test_wrong_number_of_arguments_is_an_error(self):
        for expression in [
            "LOWER()",
            "LOWER('a', 'b')",
            "UPPER()",
            "LENGTH()",
            "LENGTH('a', 'b')",
            "ABS()",
            "ABS(1, 2)",
            "ROUND()",
            "ROUND(1, 2, 3)",
            "COALESCE()",
        ]:
            with self.subTest(expression=expression):
                self.assertExpressionError(expression)

    def test_wrong_argument_types_are_errors(self):
        for expression in [
            "LOWER(1)",
            "UPPER(TRUE)",
