class OrderByTests(OrderLimitTestCase):
    def test_without_order_by_rows_keep_file_order(self):
        self.assertEqual(
            self.rows("SELECT name FROM items"),
            [("b",), ("a",), ("c",), ("d",), ("e",)],
        )

    def test_order_by_column_ascending_puts_nulls_first(self):
        self.assertEqual(
            self.rows("SELECT name FROM items ORDER BY price"),
            [("a",), ("e",), ("d",), ("b",), ("c",)],
        )

    def test_order_by_column_descending_puts_nulls_last(self):
        self.assertEqual(
            self.rows("SELECT name FROM items ORDER BY price DESC"),
            [("b",), ("c",), ("d",), ("a",), ("e",)],
        )

    def test_explicit_asc(self):
        self.assertEqual(
            self.rows("SELECT name FROM items ORDER BY price ASC"),
            [("a",), ("e",), ("d",), ("b",), ("c",)],
        )

    def test_multiple_order_items(self):
        self.assertEqual(
            self.rows("SELECT name FROM items ORDER BY price ASC, name DESC"),
            [("e",), ("a",), ("d",), ("c",), ("b",)],
        )

    def test_order_by_output_position(self):
        self.assertEqual(
            self.rows("SELECT name, price FROM items ORDER BY 2 DESC, 1 ASC"),
            [("b",), ("c",), ("d",), ("a",), ("e",)],
        )

    def test_order_by_first_output_position_descending(self):
        self.assertEqual(
            self.rows("SELECT name FROM items ORDER BY 1 DESC"),
            [("e",), ("d",), ("c",), ("b",), ("a",)],
        )

    def test_order_by_output_alias(self):
        self.assertEqual(
            self.rows("SELECT name, price AS p FROM items ORDER BY p DESC"),
            [("b",), ("c",), ("d",), ("a",), ("e",)],
        )

    def test_output_alias_matching_input_column_takes_precedence(self):
        rows = self.rows(
            "SELECT name, price * -1 AS price FROM items ORDER BY price DESC"
        )
        self.assertEqual(
            rows,
            [("d", -1), ("b", -2), ("c", -2), ("a", None), ("e", None)],
        )

    def test_order_by_output_name_is_case_insensitive(self):
        self.assertEqual(
            self.rows("SELECT name, price AS P FROM items ORDER BY p DESC"),
            [("b",), ("c",), ("d",), ("a",), ("e",)],
        )

    def test_order_by_expression_not_in_output(self):
        self.assertEqual(
            self.rows("SELECT name FROM items ORDER BY price * -1"),
            [("a",), ("e",), ("b",), ("c",), ("d",)],
        )

    def test_order_by_string_expression(self):
        self.assertEqual(
            self.rows("SELECT name FROM items ORDER BY LOWER(name) DESC"),
            [("e",), ("d",), ("c",), ("b",), ("a",)],
        )

    def test_strings_sort_by_code_point(self):
        self.assertEqual(
            self.rows("SELECT v FROM strings ORDER BY v"),
            [("A",), ("B",), ("a",), ("b",)],
        )
        self.assertEqual(
            self.rows("SELECT v FROM strings ORDER BY v DESC"),
            [("b",), ("a",), ("B",), ("A",)],
        )

    def test_sorting_is_stable_for_equal_keys(self):
        self.assertEqual(
            self.rows("SELECT v FROM dups ORDER BY k"),
            [("a",), ("b",), ("d",), ("c",)],
        )
        self.assertEqual(
            self.rows("SELECT v FROM dups ORDER BY k DESC"),
            [("c",), ("a",), ("b",), ("d",)],
        )

    def test_equal_numbers_compare_equal_and_keep_their_order(self):
        self.assertEqual(
            self.rows("SELECT v FROM numties ORDER BY v"),
            [(0.5,), (1,), (1.0,)],
        )

    def test_order_by_expression_can_use_grouped_values(self):
        # A grouped query sorted by a bare grouped column.
        self.assertEqual(
            self.rows("SELECT k, COUNT(*) FROM dups GROUP BY k ORDER BY k DESC"),
            [(2, 1), (1, 3)],
        )

    def test_order_by_position_out_of_range_is_an_error(self):
        self.assertQueryError("SELECT name FROM items ORDER BY 2")
        self.assertQueryError("SELECT name, price FROM items ORDER BY 3")

    def test_order_by_position_zero_is_an_error(self):
        self.assertQueryError("SELECT name FROM items ORDER BY 0")


